"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50579"],{29634(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.recurso_da_etapa.ancora_em_ato_irreversivel","status":422,"titulo":"O evento que inicia o prazo do recurso da etapa n\xe3o pode ser ato de efeito irrevers\xedvel; escolha outro ato"},"descricao":{"codigo":"uniplus.selecao.recurso_da_etapa.ancora_em_ato_irreversivel","requisitos":["UNI-REQ-0080","UNI-REQ-0166"],"oQueAconteceu":["O prazo de recurso de uma etapa \xe9 contado a partir de um tipo de ato que o cat\xe1logo\\nclassifica como de **efeito irrevers\xedvel**.","Ato de efeito irrevers\xedvel concede um direito que n\xe3o se desfaz. Um recurso contra ele\\nn\xe3o teria o que reverter. O recurso cab\xedvel \xe9 contra o **resultado que fundamenta** o\\nato, e \xe9 da publica\xe7\xe3o desse resultado que o prazo come\xe7a.","A classifica\xe7\xe3o \xe9 lida do cat\xe1logo a cada configura\xe7\xe3o, e n\xe3o de uma c\xf3pia guardada\\nna etapa: se o cadastro do tipo de ato muda, a confer\xeancia acompanha."],"comoResolver":["A mensagem da recusa nomeia o tipo de ato declarado como in\xedcio do prazo. Aponte a regra\\npara o resultado preliminar que fundamenta aquele ato e que a **pr\xf3pria etapa**\\npublica. Se ele ainda n\xe3o est\xe1 entre os produtos da etapa, acrescente-o, com papel\\npreliminar, e conte o prazo a partir dele.","Se quem publica esse resultado \xe9 outra fase ou etapa, a regra de recurso pertence a\\nela: mova a regra para l\xe1. O mesmo problema na fase tem\\n[p\xe1gina pr\xf3pria](/erros/uniplus.selecao.regra_recurso_fase.ancora_em_ato_irreversivel)."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);